export function initHome(){const n=document.getElementsByClassName("thumbnail-video");if(n.length!==0){let t=0,i=!1;const r=async()=>{while(i){if(n.length===0)return;const i=n[t];i.currentTime=0;await i.play();await new Promise(n=>setTimeout(n,4e3));i.pause();i.currentTime=0;t=(t+1)%n.length}},u=()=>{i=!0,r()},f=()=>{i=!1,Array.from(n).forEach(n=>{n.pause(),n.currentTime=0}),t=0};u()}}